const token=location.hash.slice(1),status=document.querySelector('#appointment-status'),cancel=document.querySelector('#cancel-appointment');const labels={pending:'Ожидает одобрения врачом. Время удерживается до 24 часов.',approved:'Врач одобрил заявку.',rejected:'Врач отклонил заявку. Выберите другое время или напишите в WhatsApp.',expired:'Время ожидания истекло. Слот освобождён.',cancelled:'Заявка отменена.'};async function request(method='GET'){try{if(!/^[a-f0-9]{64}$/.test(token))throw new Error('Откройте секретную ссылку, полученную при записи.');const r=await fetch('/api/appointment',{method,headers:{Authorization:'Bearer '+token},cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error||'Не удалось получить заявку.');if(method==='DELETE')return request();status.textContent=`${data.date} · ${data.time} · ${data.city==='astana'?'Астана':'Павлодар'} — ${labels[data.status]}`;cancel.hidden=!['pending','approved'].includes(data.status);}catch(e){status.textContent=e.message;cancel.hidden=true;}}cancel.addEventListener('click',()=>{if(confirm('Отменить заявку и освободить время?'))request('DELETE');});request();setInterval(()=>{if(!document.hidden)request();},30000);
